/*
 * emit_ninja.c - standalone build.ninja fragment emitter.
 *
 * Uses ninja's native depfile protocol, the same convention as
 * thorn's rule cc, so fragments compose with thorn-generated files.
 * Rules are namespaced per crate; multi-crate fragments aggregate an
 * `all` phony spanning every archive and verification stamp.
 *
 * Part of thorn-rs, the zero-cargo Rust staticlib companion for thorn.
 * Copyright (c) 2026 abit-foggy
 * SPDX-License-Identifier: BSD-2-Clause
 */

#include <string.h>

#include "include/emit.h"
#include "include/plan.h"
#include "include/verify.h"

static const char *
base_name(const char *p)
{
    const char *b = strrchr(p, '/');
    return b ? b + 1 : p;
}

static int
validate_paths(const RustCrate *c)
{
    struct {
        const char *path;
        const char *what;
    } checks[] = {
        { c->frag, "fragment path"   },
        { c->out,  "artifact path"   },
        { c->root, "crate root path" },
    };
    for (size_t i = 0; i < sizeof(checks) / sizeof(checks[0]); i++) {
        if (!path_safe(checks[i].path)) {
            diag("%s contains characters that are unsafe in build "
                 "fragments: '%s'", checks[i].what, checks[i].path);
            return THORN_RS_EXIT_SCAN;
        }
    }
    return 0;
}

int
emit_ninja_set(const RustCrate *const *crates, size_t count,
               const char *tool, FILE *out)
{
    if (count == 0)
        return 0;

    char stamps[64][512];
    if (count > 64) {
        diag("at most 64 crates per fragment");
        return THORN_RS_EXIT_SCAN;
    }

    fprintf(out, "# %s - generated by thorn-rs %s, do not edit\n",
            base_name(crates[0]->frag), THORN_RS_VERSION);
    fprintf(out, "# %zu crate%s (deterministic: same inputs, same "
                 "bytes)\n\n", count, count == 1 ? "" : "s");
    fprintf(out, "ninja_required_version = 1.3\n");
    fprintf(out, "rustc = %s\n", tool);

    int any_verify = 0;
    for (size_t i = 0; i < count; i++)
        if (crates[i]->header[0])
            any_verify = 1;
    if (any_verify)
        fprintf(out, "thorn_rs = thorn-rs\n");
    fprintf(out, "\n");

    for (size_t i = 0; i < count; i++) {
        const RustCrate *c = crates[i];

        int rc = validate_paths(c);
        if (rc)
            return rc;

        char flags[2048];
        if (plan_rustflags(c, flags, sizeof(flags))) {
            diag("cannot plan rustc flags for crate '%s'", c->name);
            return THORN_RS_EXIT_SCAN;
        }

        fprintf(out, "rule rustc_%s\n", c->name);
        fprintf(out, "  command = $rustc --edition $edition --crate-name "
                     "$crate_name --crate-type staticlib $rustflags "
                     "--emit=dep-info=$out.d,link=$out $in\n");
        fprintf(out, "  depfile = $out.d\n");
        fprintf(out, "  deps = gcc\n");
        fprintf(out, "  description = rustc $crate_name -> $out\n\n");

        fprintf(out, "build %s: rustc_%s %s\n", c->out, c->name, c->root);
        fprintf(out, "  crate_name = %s\n", c->name);
        fprintf(out, "  edition = %s\n", c->edition);
        fprintf(out, "  rustflags =%s\n", flags);

        if (c->header[0]) {
            char vcmd[4096];
            if (verify_command(c->out, c->header, &c->capi_syms, vcmd,
                               sizeof(vcmd))) {
                diag("cannot plan the verification command for crate "
                     "'%s'", c->name);
                return THORN_RS_EXIT_SCAN;
            }
            snprintf(stamps[i], sizeof(stamps[i]),
                     ".thorn-rs/%s.verified", c->name);
            fprintf(out, "\nrule rust_verify_%s\n", c->name);
            fprintf(out, "  command = mkdir -p .thorn-rs && $thorn_rs %s "
                         "&& touch $out\n", vcmd);
            fprintf(out, "  description = VERIFY C-ABI %s\n\n", c->name);
            fprintf(out, "build %s: rust_verify_%s %s %s\n", stamps[i],
                    c->name, c->out, c->header);
            any_verify = 1;
        } else {
            stamps[i][0] = '\0';
        }
        fprintf(out, "\n");
    }

    if (count > 1) {
        fprintf(out, "build all: phony");
        for (size_t i = 0; i < count; i++) {
            fprintf(out, " %s", crates[i]->out);
            if (stamps[i][0])
                fprintf(out, " %s", stamps[i]);
        }
        fprintf(out, "\n");
        fprintf(out, "default all\n");
    }
    return 0;
}
